refsection.programlisting:
F = gf_create_field(2, 4);
a = [0 1 0 0];                    // alpha
b = [1 1 0 0];                    // 1 + alpha = alpha^4
c = gf_multiply(F, a, b)          // [0 1 1 0]
gf_to_exponential(F, c)           // 5

// alpha por alpha^0, alpha^1, alpha^2
gf_multiply(F, F(4)(2:4, :), a)

P = gf_create_field(7, 1);
gf_multiply(P, [3 4 5], 6)        // [4 3 2]
